/*
 * TOML configuration file (`c236t.toml`).
 *
 * Canonical layout (written by `c236t-ctl setup`):
 *
 * ```toml
 * # C236T local configuration
 * # Generated by `c236t-ctl setup`
 *
 * local_key = "your-16-byte-local-key"
 * ip = "192.168.1.100"
 * port = 6668
 * device_id = "your-device-id"
 * ```
 *
 * Plain `key = value` text was considered and rejected: TOML is unambiguous,
 * supports comments, and the serializer handles quoting/escaping correctly
 * for any 16-byte key.
 *
 * Precedence when resolving settings (highest first):
 *   1. process environment (explicit shell vars)
 *   2. `c236t.toml` / `config.toml` found from the working directory upward
 *   3. `.env` (legacy dotenv fallback)
 *   4. built-in defaults for ip/port/device_id
 */

use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

/// On-disk config. All fields optional so partial files are allowed.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct FileConfig {
    pub local_key: Option<String>,
    pub ip: Option<String>,
    pub port: Option<u16>,
    pub device_id: Option<String>,
}

/// Serde shape for (de)serialization. Kept separate so `FileConfig` stays a
/// plain struct used in tests.
#[derive(Debug, Deserialize, Serialize)]
struct FileConfigSerde {
    local_key: Option<String>,
    ip: Option<String>,
    port: Option<u16>,
    device_id: Option<String>,
}

impl FileConfig {
    pub fn from_toml(text: &str) -> Result<Self, String> {
        let parsed: FileConfigSerde =
            toml::from_str(text).map_err(|e| format!("invalid TOML config: {e}"))?;
        Ok(Self {
            local_key: parsed.local_key,
            ip: parsed.ip,
            port: parsed.port,
            device_id: parsed.device_id,
        })
    }

    pub fn to_toml(&self) -> Result<String, String> {
        let serde_cfg = FileConfigSerde {
            local_key: self.local_key.clone(),
            ip: self.ip.clone(),
            port: self.port,
            device_id: self.device_id.clone(),
        };
        let body = toml::to_string(&serde_cfg).map_err(|e| format!("could not write config: {e}"))?;
        Ok(format!(
            "# C236T local configuration\n# Generated by `c236t-ctl setup`\n\n{body}"
        ))
    }
}

/// Env var that may point at an explicit config file.
pub fn env_config_path() -> Option<PathBuf> {
    std::env::var("C236T_CONFIG_FILE")
        .or_else(|_| std::env::var("THING_CONFIG_FILE"))
        .ok()
        .map(PathBuf::from)
}

/// Canonical path `setup` writes to.
pub fn canonical_path() -> PathBuf {
    if let Some(p) = env_config_path() {
        return p;
    }
    PathBuf::from("c236t.toml")
}

/// Locate the config file: env override, then `./c236t.toml`,
/// `./config.toml`, walking up parents (mirrors dotenv's upward search).
pub fn find_config_file() -> Option<PathBuf> {
    if let Some(p) = env_config_path() {
        if p.exists() {
            return Some(p);
        }
        return None;
    }
    let mut dir: Option<PathBuf> = std::env::current_dir().ok();
    while let Some(d) = dir {
        for name in ["c236t.toml", "config.toml"] {
            let candidate = d.join(name);
            if candidate.is_file() {
                return Some(candidate);
            }
        }
        dir = d.parent().map(|p| p.to_path_buf());
    }
    None
}

/// Load the config file if present. Missing file => `Ok(None)`.
/// Unparsable file => `Err` with the underlying TOML error.
pub fn load_file_config() -> Result<Option<FileConfig>, String> {
    let path = match find_config_file() {
        Some(p) => p,
        None => return Ok(None),
    };
    let text = std::fs::read_to_string(&path)
        .map_err(|e| format!("could not read {}: {e}", path.display()))?;
    FileConfig::from_toml(&text).map(Some)
}

/// Parse a TOML string (helper for tests / callers with the text).
pub fn parse_config_str(text: &str) -> Result<FileConfig, String> {
    FileConfig::from_toml(text)
}

/// Write the config file, restricting permissions to `0600` on Unix.
pub fn save_file_config(path: &Path, cfg: &FileConfig) -> Result<(), String> {
    let text = cfg.to_toml()?;
    std::fs::write(path, &text).map_err(|e| format!("could not write {}: {e}", path.display()))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(
            path,
            std::fs::Permissions::from_mode(0o600),
        );
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_minimal_config() {
        let cfg = FileConfig::from_toml(
            r#"
local_key = "0123456789abcdef"
ip = "192.168.1.100"
port = 6668
device_id = "example-device-id"
"#,
        )
        .unwrap();
        assert_eq!(cfg.local_key.as_deref(), Some("0123456789abcdef"));
        assert_eq!(cfg.ip.as_deref(), Some("192.168.1.100"));
        assert_eq!(cfg.port, Some(6668));
        assert_eq!(cfg.device_id.as_deref(), Some("example-device-id"));
    }

    #[test]
    fn roundtrip_preserves_special_chars() {
        // Keys may contain ", $, \, ', — TOML must round-trip them.
        let original = FileConfig {
            local_key: Some("a\"b$c\\d'e1234567".to_string()),
            ip: Some("192.168.1.100".to_string()),
            port: Some(6668),
            device_id: Some("example-device-id".to_string()),
        };
        let text = original.to_toml().unwrap();
        let parsed = FileConfig::from_toml(&text).unwrap();
        assert_eq!(parsed, original);
    }

    #[test]
    fn partial_config_is_allowed() {
        let cfg = FileConfig::from_toml(r#"ip = "192.168.1.10""#).unwrap();
        assert_eq!(cfg.ip.as_deref(), Some("192.168.1.10"));
        assert_eq!(cfg.local_key, None);
    }

    #[test]
    fn rejects_bad_toml() {
        assert!(FileConfig::from_toml("port = ").is_err());
    }
}
